WITH history AS (SELECT *,AVG(ridership) OVER(PARTITION BY station_id ORDER BY day::timestamp RANGE BETWEEN INTERVAL '30 days' PRECEDING AND INTERVAL '1 day' PRECEDING) AS baseline,STDDEV_SAMP(ridership) OVER(PARTITION BY station_id ORDER BY day::timestamp RANGE BETWEEN INTERVAL '30 days' PRECEDING AND INTERVAL '1 day' PRECEDING) AS deviation FROM station_daily_stats) SELECT *, (ridership-baseline)/NULLIF(deviation,0) AS z_score FROM history; -- Exploratory only: weekday seasonality and missing days need review.
